//! 🪡️ Captured fields retain their actual typed projection and original Work.
use super::{ProjectionField,SnapshotProjection};
use crate::{RetirementDemand,ValueError,ValueRefusalKind,RetainedAllocationEffect,OriginalRetirementFailure,OriginalRetirementPoll,retained_clone::{RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedOwnedProjectionAdmission,RetainedNativeFieldProjection,RetainedCursorRelease,OriginalEffectReply,OriginalEffectReplyComplete,OriginalEffectInvocationIdentity,OriginalEffectCallbackMode,OriginalWorkBindingIdentity,OriginalWorkActionBoundary,OriginalRetirementCloseLoan,retained_clone_grant_admits}};
use std::mem::{size_of,ManuallyDrop,MaybeUninit};
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
/// 🧳️ One actual typed child, projected alias and Work owner remain resident through every action.
pub struct CapturedProjectionField<R:Sync+'static,T:SnapshotProjection>{witness:RetainedNativeFieldProjection<R,T>,projection:ManuallyDrop<RetainedOwnedProjectionAdmission<T>>,field:ManuallyDrop<ProjectionField<T>>,work:Option<OriginalWorkBindingIdentity>,closing:bool,advance_route:Option<(OriginalEffectInvocationIdentity,(u64,usize,usize,usize),usize,u64,OriginalWorkActionBoundary,RetainedCloneGrant)>,close_route:Option<(OriginalEffectInvocationIdentity,u8,Option<(semio_framework_value_control_contract::NativeAllocationIdentity,Option<u64>,OriginalWorkBindingIdentity)>,(crate::RetirementDemand,u64,crate::retained_clone::OriginalWorkActionBoundary),usize)>}
impl<R:Sync+'static,T:SnapshotProjection> CapturedProjectionField<R,T>{
 /// 🌱️ Constructs only an empty native seed; it allocates and calls out to nothing.
 pub fn new(witness:RetainedNativeFieldProjection<R,T>)->Self{Self{witness,projection:ManuallyDrop::new(Default::default()),field:ManuallyDrop::new(Default::default()),work:None,closing:false,advance_route:None,close_route:None}}
 fn authenticate(&self,effect:&RetainedAllocationEffect<'_>)->Result<(),ValueError>{if !self.work.is_some_and(|work|work.matches_effect(effect)){return Err(invalid("captured field changed original Source or Work"))}Ok(())}
 /// 📏️ Selects the actual Work binding, native field projection or child frontier.
 pub fn demands(&self,source:RetainedCloneRef<'_,R>,body:usize,maximum:u64)->Result<RetirementDemand,ValueError>{if self.closing||self.advance_route.is_some()||self.close_route.is_some(){return Err(invalid("captured field is closing or occupied"))}if maximum==0{return Ok(Default::default())}if self.work.is_none(){return Ok(RetirementDemand{copy_bytes:size_of::<Option<OriginalWorkBindingIdentity>>(),depth:1,..Default::default()})}if self.projection.terminal_is_empty(){return self.witness.demand(source,&self.projection)}self.field.demands(self.projection.borrow()?,body,maximum)}
 /// ⛽️ Quotes the same selected original action.
 pub fn advance_work_demand(&self,source:RetainedCloneRef<'_,R>,body:usize,maximum:u64)->Result<u64,ValueError>{self.demands(source,body,maximum)?;if maximum==0{return Ok(0)}let work=if self.work.is_none(){1}else if self.projection.terminal_is_empty(){self.witness.work_demand(source,&self.projection)?}else{self.field.advance_work_demand(self.projection.borrow()?,body,maximum)?};Ok(if work<=maximum{work}else{0})}
 /// 📥️ Drives only the selected actual producer and records directly in the original reply.
 pub fn advance_into<'r>(&mut self,source:RetainedCloneRef<'_,R>,body:usize,maximum:u64,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{let d=self.demands(source,body,maximum)?;let work=self.advance_work_demand(source,body,maximum)?;if work==0||effect.remaining_work_units()?<work||!retained_clone_grant_admits(effect.grant(),d){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if effect.work_source_turn().is_none(){return Err(invalid("captured field lacks original Source"))}if self.work.is_none(){if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"captured field Work binding exceeded its limit").into())))}self.work=Some(OriginalWorkBindingIdentity::from_effect(effect));return Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}self.authenticate(effect)?;if self.projection.terminal_is_empty(){let mut result=None;let inner=OriginalEffectReply::borrow(&mut result)?;drop(self.witness.admit_into(source,&mut self.projection,effect,inner)?);return crate::forward_original_value_reply(&mut result,reply.progress())}let invocation=effect.invocation().ok_or_else(||invalid("captured field lacks invocation"))?;if invocation.mode()!=OriginalEffectCallbackMode::Receive||invocation.source_turn()!=effect.work_source_turn(){return Err(invalid("captured field changed original invocation"))}let key=(invocation.identity(),source.reference_identity(),body,maximum,effect.action_boundary(),effect.grant());self.advance_dispatch(source,body,maximum,effect,reply,key,false)}
 /// 🔁️ Recovers the same captured child, original request and Work action.
 pub fn recover_advance_into<'r>(&mut self,source:RetainedCloneRef<'_,R>,body:usize,maximum:u64,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.authenticate(effect)?;let key=self.advance_route.ok_or_else(||invalid("captured field recovery absent"))?;let invocation=effect.invocation().ok_or_else(||invalid("captured field recovery lacks invocation"))?;if invocation.mode()!=OriginalEffectCallbackMode::Recover||invocation.identity()!=key.0||source.reference_identity()!=key.1||body!=key.2||maximum!=key.3||effect.grant()!=key.5||invocation.source_turn()!=effect.work_source_turn(){return Err(invalid("captured field recovery changed original request"))}self.advance_dispatch(source,body,maximum,effect,reply,key,true)}
 fn advance_dispatch<'r>(&mut self,_source:RetainedCloneRef<'_,R>,body:usize,maximum:u64,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>,key:(OriginalEffectInvocationIdentity,(u64,usize,usize,usize),usize,u64,OriginalWorkActionBoundary,RetainedCloneGrant),recover:bool)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{let spent=effect.performed_since_action(key.4)?;let remaining=u128::from(maximum).checked_sub(spent).and_then(|n|u64::try_from(n).ok()).ok_or_else(||invalid("captured field exceeded original Work"))?.min(effect.remaining_work_units()?);let mut child=effect.reborrow(effect.grant(),remaining)?;let state=self;let mut scope=reply.progress().scope(&mut state.advance_route,key)?;let original=state.projection.borrow()?;let done=if recover{state.field.recover_advance_into(original,body,maximum,&mut child,scope.borrow()?)?}else{state.field.advance_into(original,body,maximum,&mut child,scope.borrow()?)?};drop(done);Ok(scope.forwarded())}
 /// ✅️ Reports readiness without moving the retained field.
 pub fn ready(&self)->bool{!self.closing&&self.field.ready()}
 /// 👁️ Borrows the admitted actual projected value without moving it.
 pub fn value(&self)->Option<&T>{if self.ready(){self.field.value()}else{None}}
 /// 📏️ Quotes placement into the original caller-resident destination.
 pub fn place_demand(&self)->Result<RetirementDemand,ValueError>{self.field.place_demand()}
 /// 🫴️ Places the same output under its original effect and borrowed reply.
 pub fn place_into<'r>(&mut self,target:&mut MaybeUninit<T>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.authenticate(effect)?;self.field.place_into(target,effect,reply)}
 /// 🚦️ Reports whether this frame selected its paid close start.
 pub fn close_started(&self)->bool{self.closing}
 /// 📏️ Quotes the native close-intent header.
 pub fn begin_close_demand(&self)->Result<RetirementDemand,ValueError>{Ok(if self.closing{Default::default()}else{RetirementDemand{copy_bytes:size_of::<bool>(),depth:1,..Default::default()}})}
 /// ⛽️ Quotes native close-intent Work.
 pub fn begin_close_work_demand(&self)->Result<u64,ValueError>{Ok(u64::from(!self.closing))}
 /// 🚦️ Pays and records close intent without starting a child.
 pub fn begin_close_into<'r>(&mut self,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{if self.advance_route.is_some(){return Err(invalid("captured field retains its advance"))}if self.work.is_some(){self.authenticate(effect)?}if self.closing{return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))}let d=self.begin_close_demand()?;if effect.remaining_work_units()?<1||!retained_clone_grant_admits(effect.grant(),d){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"captured field close exceeded original Work").into())))}self.closing=true;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
 /// 🔁️ Native close intent records before returning and cannot be replayed.
 pub fn recover_begin_close_into<'r>(&mut self,_:&mut RetainedAllocationEffect<'_>,_:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{Err(invalid("native captured-field close start has no unrecorded callback"))}
 /// 📏️ Quotes the actual selected child, alias or Work-header close.
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing||self.advance_route.is_some()||self.close_route.is_some(){return Err(invalid("captured field close is not ready"))}if !self.field.close_started(){return self.field.begin_close_demand()}if !self.field.terminal_is_empty(){return self.field.close_demands(body)}if !self.projection.terminal_is_empty(){return self.projection.close_demand(body)}if self.work.is_some(){return Ok(RetirementDemand{copy_bytes:size_of::<Option<OriginalWorkBindingIdentity>>(),depth:1,..Default::default()})}Ok(Default::default())}
 /// ⛽️ Quotes Work for the same selected close frontier.
 pub fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{self.close_demands(body)?;if !self.field.close_started(){self.field.begin_close_work_demand()}else if !self.field.terminal_is_empty(){self.field.close_work_demand(body)}else if !self.projection.terminal_is_empty(){self.projection.close_work_demand(body)}else{Ok(u64::from(self.work.is_some()))}}
 /// 🍼️ Selects an actual child Birth before opening a general effect.
 pub fn requires_original_birth(&self)->bool{if self.close_route.is_some()||self.advance_route.is_some(){return false}if self.field.requires_original_birth(){true}else if self.field.terminal_is_empty(){self.projection.requires_original_birth()}else{false}}
 /// 🧵️ Drives that selected child through the same original loan.
 pub fn close_original_birth_step(&mut self,original:&mut OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->OriginalRetirementPoll{match original.original_work().binding_identity(){Ok(work)if self.work==Some(work)=>{},Ok(_)=>return crate::retained_clone::RetainedWorkPoll::Complete(crate::RetainedWorkOutcome{result:Err(invalid("captured field Birth changed Work").into()),work:0}),Err(error)=>return crate::retained_clone::RetainedWorkPoll::Complete(crate::RetainedWorkOutcome{result:Err(error.into()),work:0})}if self.field.requires_original_birth(){self.field.close_original_birth_step(original,grant)}else{self.projection.close_original_birth_step(original,grant)}}
 /// 🔑️ Reports the selected actual original close-control frontier.
 pub fn requires_original_control(&self)->bool{if let Some((_,route,_,_,_))=self.close_route{return route>=5}if self.advance_route.is_some(){return false}if self.field.requires_original_control(){true}else if self.field.terminal_is_empty(){self.projection.requires_original_control()}else{false}}
 /// 📬️ Lends the caller reply directly to the selected close producer.
 pub fn close_into<'r>(&mut self,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.close_dispatch(None,body,effect,reply,false,false)}
 /// 🔁️ Recovers the same ordinary close action.
 pub fn recover_close_into<'r>(&mut self,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.close_dispatch(None,body,effect,reply,true,false)}
 /// 🧵️ Lends the same original close loan to the selected child.
 pub fn close_original_into<'r>(&mut self,original:&mut OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.close_dispatch(Some(original),body,effect,reply,false,false)}
 /// 🔁️ Recovers the same original-loan close action.
 pub fn recover_close_original_into<'r>(&mut self,original:&mut OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.close_dispatch(Some(original),body,effect,reply,true,false)}
 /// 🧵️ Drives a selected original child close during field preparation.
 pub fn advance_original_into<'r>(&mut self,original:&mut OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.close_dispatch(Some(original),body,effect,reply,false,true)}
 /// 🔁️ Recovers that selected original child close during preparation.
 pub fn recover_advance_original_into<'r>(&mut self,original:&mut OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{self.close_dispatch(Some(original),body,effect,reply,true,true)}
 fn close_dispatch<'r>(&mut self,mut original:Option<&mut OriginalRetirementCloseLoan<'_>>,body:usize,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,OriginalRetirementFailure>,recover:bool,during_advance:bool)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,OriginalRetirementFailure>,ValueError>{if self.work.is_some(){self.authenticate(effect)?}if self.advance_route.is_some()||(!self.closing&&!during_advance){return Err(invalid("captured field close is not selected"))}let invocation=effect.invocation().ok_or_else(||invalid("captured field close lacks invocation"))?;let mode=if recover{OriginalEffectCallbackMode::Recover}else{OriginalEffectCallbackMode::Receive};if invocation.mode()!=mode||invocation.source_turn()!=effect.work_source_turn(){return Err(invalid("captured field close changed original action"))}let binding=match original.as_mut(){Some(loan)=>{let binding=loan.original_work().binding_identity()?;if !binding.matches_effect(effect){return Err(invalid("captured field close changed Work"))}Some((loan.ledger_identity(),loan.retirement_recipient_identity(),binding))},None=>None};let body=if recover{self.close_route.map_or(body,|key|key.4)}else{body};let route=if recover{let key=self.close_route.ok_or_else(||invalid("captured field close recovery absent"))?;if key.0!=invocation.identity()||key.2!=binding{return Err(invalid("captured field close recovery changed owner"))}if !effect.admits_recovery(key.3.0,key.3.1,key.3.2)?{return Ok(reply.pending())}key.1}else{if self.close_route.is_some(){return Err(invalid("captured field close action occupied"))}if !self.field.close_started(){if original.is_some(){return Err(invalid("captured field close-start is not original"))}1}else if !self.field.terminal_is_empty(){if original.is_some(){5}else{2}}else if !self.projection.terminal_is_empty(){if original.is_some(){6}else{3}}else if self.work.is_some(){if original.is_some(){return Err(invalid("captured field Work clear is not original"))}4}else{return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))}};if !recover&&!during_advance{let d=self.close_demands(body)?;let work=self.close_work_demand(body)?;if effect.remaining_work_units()?<work||!retained_clone_grant_admits(effect.grant(),d){return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}}if route==4{if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(ValueRefusalKind::WorkLimit,"captured field Work release exceeded its limit").into())))}self.work=None;return Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<Option<OriginalWorkBindingIdentity>>(),..Default::default()}))))}let key=(invocation.identity(),route,binding,match self.close_route{Some(key)=>key.3,None=>(self.close_demands(body)?,self.close_work_demand(body)?,effect.action_boundary())},body);let state=self;let mut scope=reply.progress().scope(&mut state.close_route,key)?;let done=match(route,recover,original){(1,false,None)=>state.field.begin_close_into(effect,scope.borrow()?)?,(1,true,None)=>state.field.recover_begin_close_into(effect,scope.borrow()?)?,(2,false,None)=>state.field.close_into(body,effect,scope.borrow()?)?,(2,true,None)=>state.field.recover_close_into(body,effect,scope.borrow()?)?,(3,false,None)=>state.projection.close_into(body,effect,scope.borrow()?)?,(3,true,None)=>state.projection.recover_close_into(body,effect,scope.borrow()?)?,(5,false,Some(loan))=>if during_advance{state.field.advance_original_into(loan,body,effect,scope.borrow()?)?}else{state.field.close_original_into(loan,body,effect,scope.borrow()?)?},(5,true,Some(loan))=>if during_advance{state.field.recover_advance_original_into(loan,body,effect,scope.borrow()?)?}else{state.field.recover_close_original_into(loan,body,effect,scope.borrow()?)?},(6,false,Some(loan))=>state.projection.close_original_into(loan,body,effect,scope.borrow()?)?,(6,true,Some(loan))=>state.projection.recover_close_original_into(loan,body,effect,scope.borrow()?)?,_=>return Err(invalid("captured field close route changed"))};drop(done);Ok(scope.forwarded())}
 /// ✅️ Every child, alias and Work owner has completed its paid close.
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.field.terminal_is_empty()&&self.projection.terminal_is_empty()&&self.work.is_none()&&self.advance_route.is_none()&&self.close_route.is_none()}
 /// 🧹️ Proves that the actual terminal native frame has no remaining owned payload.
 pub fn native_terminal_release(&self)->Option<RetainedCursorRelease<Self>>{if !self.terminal_is_empty(){return None}Some(unsafe{RetainedCursorRelease::native(|owner:&Self|owner.terminal_is_empty())})}
}
impl<R:Sync+'static,T:SnapshotProjection> Drop for CapturedProjectionField<R,T>{fn drop(&mut self){if std::thread::panicking(){return}assert!(self.field.terminal_is_empty()&&self.projection.terminal_is_empty()&&self.work.is_none()&&self.advance_route.is_none()&&self.close_route.is_none(),"captured field retains an original owner or action");unsafe{ManuallyDrop::drop(&mut self.field);ManuallyDrop::drop(&mut self.projection)}}}

impl<R:Sync+'static,T:crate::retained_clone::RetainedClone,const N:usize> CapturedProjectionField<R,[T;N]>{
 /// 🪡️ Lends the actual captured array output to its resident typed placement.
 /// # Safety
 /// The parent must uphold the stable, exclusive and uninitialized destination contract of `NativeArrayFieldPlacement::admit_into`.
 pub unsafe fn begin_array_placement<'r>(&mut self,target:&mut MaybeUninit<[T;N]>,owner:&mut Option<crate::snapshot_projection::NativeArrayFieldPlacement<T,N>>,effect:&mut RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'r,RetainedCloneStep,ValueError>)->Result<OriginalEffectReplyComplete<'r,RetainedCloneStep,ValueError>,ValueError>{self.authenticate(effect)?;unsafe{self.field.begin_array_placement(target,owner,effect,reply)}}
}
